//! 🔹️ Authored singleton recipes bind one primitive input to its exact retained inner branch and inverse.
use super::*;
pub(super) fn compile(input:&DeriveInput,schema:&Value,recipe:&Value,contract:&Path,snapshot:&Path,diff:&Path)->syn::Result<Tokens>{
 let syn::Data::Struct(data)=&input.data else{return Err(error("native singleton requires a payload record"));};let syn::Fields::Named(fields)=&data.fields else{return Err(error("native singleton requires named fields"));};if fields.named.len()!=1{return Err(error("native singleton must declare its sole authored field"));}
 let authored=ident(recipe,"input")?;let field=ident(recipe,"field")?;let payload=fields.named.first().unwrap();if payload.ident.as_ref()!=Some(&authored){return Err(error("native singleton input disagrees with its actual payload"));}let scalar=&payload.ty;let Type::Path(path)=scalar else{return Err(error("native singleton scalar has no fixed representation"));};let scalar_name=path.path.segments.last().unwrap().ident.to_string();let property=&schema["properties"][camel(&authored.to_string())];let expected=match scalar_name.as_str(){"f64"=>"number","u8"|"u16"|"u32"=>"integer",_=>return Err(error("native singleton primitive has no fixed original producer"))};if text(property,"type")?!=expected{return Err(error("native singleton type disagrees with its authored schema"));}
 let mut checks=Vec::new();if scalar_name=="f64"{checks.push(quote!(value.is_finite()));}for(name,relation)in[("minimum",0u8),("exclusiveMinimum",1),("maximum",2),("exclusiveMaximum",3)]{if let Some(bound)=property.get(name){let literal=match scalar_name.as_str(){"f64"=>{let n=bound.as_f64().filter(|n|n.is_finite()).ok_or_else(||error("singleton bound must be finite"))?;quote!(#n)},"u8"=>{let n=bound.as_u64().and_then(|n|u8::try_from(n).ok()).ok_or_else(||error("singleton bound exceeds u8"))?;quote!(#n)},"u16"=>{let n=bound.as_u64().and_then(|n|u16::try_from(n).ok()).ok_or_else(||error("singleton bound exceeds u16"))?;quote!(#n)},_=>{let n=bound.as_u64().and_then(|n|u32::try_from(n).ok()).ok_or_else(||error("singleton bound exceeds u32"))?;quote!(#n)}};checks.push(match relation{0=>quote!(value>=#literal),1=>quote!(value>#literal),2=>quote!(value<=#literal),_=>quote!(value<#literal)});}}
 let valid=if checks.is_empty(){quote!(true)}else{quote!(#(#checks)&&*)};let scope=ident(recipe,"scope")?;let (branch,output,context)=match scope.to_string().as_str(){"site"=>(quote!(#snapshot::state::StateSite),quote!(::semio_s_artifact_energy_model_native_mutations::row::SiteBranchOutput),quote!()),"ground_temperature"=>(quote!(#snapshot::state::StateGroundTemperatureConfig),quote!(::semio_s_artifact_energy_model_native_mutations::row::GroundBranchOutput),quote!()),"run_period"=>{if recipe.get("calendarInterval")!=Some(&Value::Bool(true)){return Err(error("native run period requires the actual interval validation policy"));}(quote!(#snapshot::state::RunPeriod),quote!(::semio_s_artifact_energy_model_native_mutations::row::RunPeriodBranchOutput),quote!(fn valid_context(value:Self::Scalar,original:&Self::Branch)->bool{let mut period=*original;period.#field=value;period.is_interval()}))},_=>return Err(error("singleton scope has no original enclosing branch producer"))};
 let name=&input.ident;let plan=format_ident!("__{}NativeFieldPath",name);let diagnostics=&recipe["diagnostics"];let invalid=diagnostic(diagnostics,"invalid",contract)?;let unchanged=diagnostic(diagnostics,"unchanged",contract)?;let contextual=if scope=="run_period"{let d=diagnostic(diagnostics,"context",contract)?;quote!(const INVALID_CONTEXT:#contract::mutation::retained::RetainedDiagnosticSpec=#d;)}else{quote!()};let semantics=&recipe["semantics"];let verb=text(semantics,"verb")?;let entity=text(semantics,"entity")?;let kind=text(semantics,"kind")?;let record=text(semantics,"record")?;let english=text(&recipe["labels"],"en")?;let german=text(&recipe["labels"],"de")?;
 Ok(quote!{
  #[doc(hidden)]pub struct #plan;
  impl ::semio_s_artifact_energy_model_native_mutations::single::SingleFieldPath for #plan{type Scalar=#scalar;type Branch=#branch;type Output=#output;fn branch(original: ::semio_framework_value::RetainedCloneRef<'_,#snapshot::original::EnergyModelSnapshot>)->::semio_framework_value::RetainedCloneRef<'_,Self::Branch>{original.project(0,|s|s.model.identity.get().#scope.get())}fn read(branch:&Self::Branch)->Self::Scalar{branch.#field}fn select(branch:&mut Self::Branch)->&mut Self::Scalar{&mut branch.#field}fn valid(value:Self::Scalar)->bool{#valid}#context fn output()->Self::Output{#output::new()}}
  impl<M:From<#name>> ::semio_s_artifact_energy_model_native_mutations::single::SingleLeafSpec<#name,M> for #plan{const INVALID:#contract::mutation::retained::RetainedDiagnosticSpec=#invalid;#contextual const UNCHANGED:#contract::mutation::retained::RetainedDiagnosticSpec=#unchanged;fn input(payload: ::semio_framework_value::RetainedCloneRef<'_,#name>)->::semio_framework_value::RetainedCloneRef<'_,Self::Scalar>{payload.project(0,|p|&p.#authored)}fn inverse(_: ::semio_framework_value::RetainedCloneRef<'_,#name>,value:Self::Scalar)->M{#name{#authored:value}.into()}}
  impl<M> #contract::mutation::retained::RetainedMutationLeaf<#snapshot::original::EnergyModelSnapshot,M> for #name where M:#contract::Mutation<#snapshot::original::EnergyModelSnapshot,Diff=#diff::original::EnergyModelDiff>+From<#name>+Send+'static{type Preparation=::semio_s_artifact_energy_model_native_mutations::single::SingleLeafPreparation<Self,M,#plan>;}
  impl<M> #contract::MutationKind<#snapshot::original::EnergyModelSnapshot,M> for #name where M:#contract::Mutation<#snapshot::original::EnergyModelSnapshot,Diff=#diff::original::EnergyModelDiff>+From<#name>{const SEMANTICS:#contract::SemanticDescriptor=#contract::SemanticDescriptor{verb:#verb,entity:#entity,kind:#kind,record:#record};fn label(&self)->#contract::LocalizedLabel{#contract::LocalizedLabel::native(#english,#german)}}
 })
}

